    ["Interface skin"] = "Oberflächen-Skin", ["WoWraVox"] = "WoWraVox", ["Clean"] = "Schlicht",
    ["Reload UI"] = "UI neu laden", ["Skin changes after /reload."] = "Skin-Änderungen gelten nach /reload.",
    ["Choose the look of the WoWraVox window. The change applies after /reload."] = "Wähle das Aussehen des WoWraVox-Fensters. Die Änderung gilt nach /reload.",
    ["Interface skin: %s (active: %s). Available: %s. Use /wvskin <name>."] = "Oberflächen-Skin: %s (aktiv: %s). Verfügbar: %s. Mit /wvskin <name> ändern.",
    ["Unknown skin: %s"] = "Unbekannter Skin: %s",
