    ["Diagnostic report"] = "Diagnosebericht",
    ["Diagnostic report unavailable."] = "Diagnosebericht nicht verfügbar.",
    ["Could not build the diagnostic report. Try /wvdebug report again."] = "Diagnosebericht konnte nicht erstellt werden. /wvdebug report erneut versuchen.",
    ["Could not open the diagnostic report. Try /wvdebug report again."] = "Diagnosebericht konnte nicht geöffnet werden. /wvdebug report erneut versuchen.",
    ["Application category"] = "Anwendungskategorie",
    ["Expiration category"] = "Ablaufkategorie",
    ["Spell ID recommended; name search may be incomplete"] = "Spell-ID empfohlen; Namenssuche kann unvollständig sein",
    ["Effect status colors"] = "Farben für Effektstatus",
    ["Each trigger row shows its combat tracking status. Green means already assigned to Tracked Buffs or Bars. Orange means available for this class/spec but not assigned yet; clicking it opens a setup prompt for Advanced Cooldown Settings."] = "Jeder Auslöser zeigt seinen Erfassungsstatus im Kampf. Grün bedeutet: bereits „Tracked Buffs“ oder „Tracked Bars“ zugeordnet. Orange bedeutet: für diese Klasse/Spezialisierung verfügbar, aber noch nicht zugeordnet. Ein Klick öffnet die Nachfrage zu den erweiterten Cooldown-Einstellungen.",
    ["Each trigger row shows its combat tracking status. The legend at the bottom maps colors to statuses. The action button on CDM rows opens settings or a setup prompt."] = "Jede Auslöserzeile zeigt den Erfassungsstatus im Kampf. Die Farblegende unten ordnet jeder Farbe einen Status zu. Der Aktionsknopf bei CDM-Zeilen öffnet die Einstellungen oder die Zuordnungsnachfrage.",
    ["Direct"] = "Direkt",
    ["Own cast"] = "Eigener Zauber",
    ["CDM tracked"] = "Im CDM erfasst",
    ["Click to open CDM"] = "Klick: CDM öffnen",
    ["Click to set up"] = "Klick: Zuordnung öffnen",
    ["Open CDM"] = "CDM öffnen",
    ["Set up"] = "Zuordnen",
    ["Tracking colors:"] = "Farblegende:",
    ["This aura is already assigned to Cooldown Manager Tracked Buffs or Bars. Its active state can serve as a combat signal. Click this row to open Advanced Cooldown Settings."] = "Diese Aura ist im Cooldown Manager bereits „Tracked Buffs“ oder „Tracked Bars“ zugeordnet. Ihr aktiver Zustand kann als Kampfsignal dienen. Klicke auf diese Zeile, um die erweiterten Cooldown-Einstellungen zu öffnen.",
    ["Available, not tracked"] = "Verfügbar, noch nicht getrackt",
    ["Not learned"] = "Nicht gelernt",
    ["Status unknown"] = "Status unbekannt",
    ["WoWraVox can read this aura in combat without a Cooldown Manager signal."] = "WoWraVox kann diese Aura im Kampf ohne Signal des Cooldown Managers lesen.",
    ["This self-buff spell is known to your current character, so WoWraVox can detect your own cast. An effect from another player may need the selected category cue."] = "Dein Charakter kennt diesen Selbstbuff-Zauber. WoWraVox kann deinen eigenen Einsatz erkennen. Kommt derselbe Effekt von einem anderen Spieler, kann der gewählte Kategoriehinweis nötig sein.",
    ["No category sound configured for effects received from another player. They may be silent in combat."] = "Für Effekte von anderen Spielern ist kein Kategorie-Sound eingestellt. Sie können im Kampf daher stumm bleiben.",
    ["Your current class/spec exposes this learned aura in Cooldown Manager, but it is not assigned to Tracked Buffs or Bars yet. Click this row for a prompt, then open Advanced Cooldown Settings and assign it manually. The category cue remains available."] = "Deine aktuelle Klasse/Spezialisierung stellt diese gelernte Aura im Cooldown Manager bereit, sie ist aber noch nicht „Tracked Buffs“ oder „Tracked Bars“ zugeordnet. Klicke auf diese Zeile und öffne über die Nachfrage die erweiterten Cooldown-Einstellungen, um die Aura manuell zuzuordnen. Der Kategoriehinweis bleibt verfügbar.",
    ["No matching trackable aura is exposed for this class/spec. If WoW hides the effect, WoWraVox can use the configured category cue; custom text may be unavailable."] = "Für diese Klasse/Spezialisierung ist keine passende erfassbare Aura verfügbar. Wenn WoW den Effekt verbirgt, kann WoWraVox den eingestellten Kategoriehinweis verwenden; eigener Text ist eventuell nicht verfügbar.",
    ["Cooldown Manager lists this as an aura for your class/spec, but marks it as not learned. WoWraVox will not suggest tracking it."] = "Der Cooldown Manager führt dies als Aura deiner Klasse/Spezialisierung, markiert sie aber als nicht gelernt. WoWraVox schlägt die Erfassung daher nicht vor.",
    ["WoWraVox could not verify this aura's Cooldown Manager eligibility. Learning mode and the configured category cue remain available."] = "WoWraVox konnte die CDM-Eignung dieser Aura nicht prüfen. Lernmodus und der eingestellte Kategoriehinweis bleiben verfügbar.",
    ["Open Advanced Cooldown Settings"] = "Erweiterte Cooldown-Einstellungen öffnen",
    ["%s (ID %d) is available for your class/spec but not assigned to Tracked Buffs or Bars. Open Advanced Cooldown Settings and assign it manually. WoWraVox cannot add it automatically. Your category cue remains available."] = "%s (ID %d) ist für deine Klasse/Spezialisierung verfügbar, aber noch nicht „Tracked Buffs“ oder „Tracked Bars“ zugeordnet. Öffne die erweiterten Cooldown-Einstellungen und ordne die Aura manuell zu. WoWraVox kann sie nicht automatisch hinzufügen. Der Kategoriehinweis bleibt verfügbar.",
    ["Open Advanced Cooldown Settings after combat."] = "Öffne nach dem Kampf die erweiterten Cooldown-Einstellungen.",
    ["Open Advanced Cooldown Settings from Edit Mode."] = "Öffne die erweiterten Cooldown-Einstellungen über den Bearbeitungsmodus.",
    ["Combat: custom text possible"] = "Kampf: eigener Text möglich",
    ["Combat: own cast"] = "Kampf: eigener Zauber",
    ["Combat: availability unknown"] = "Kampf: Verfügbarkeit unbekannt",
    ["Combat: category may be needed"] = "Kampf: Kategorie eventuell nötig",
    ["WoW exposes this effect in combat. Custom text requires TTS to be enabled."] = "WoW gibt diesen Effekt im Kampf frei. Eigener Text benötigt aktivierte Sprachausgabe.",
    ["Your current character knows this self-buff spell, so WoWraVox can use custom text for your cast. An effect from another player may need the configured category sound."] = "Dein Charakter kennt diesen Selbstbuff-Zauber. WoWraVox kann eigenen Text für deinen Einsatz verwenden. Kommt derselbe Effekt von einem anderen Spieler, kann der eingestellte Kategorie-Sound nötig sein.",
    ["Combat detection cannot currently be determined. A configured category sound may announce this effect."] = "Erkennung im Kampf ist derzeit unbekannt. Ein konfigurierter Kategorieton kann diesen Effekt ansagen.",
    ["WoW may hide this effect in combat. Custom text may be unavailable; the configured category sound can announce it instead."] = "WoW kann diesen Effekt im Kampf verbergen. Eigener Text kann dann ausbleiben; der konfigurierte Kategorieton kann ihn stattdessen ansagen.",
    ["Application category: %s"] = "Anwendungskategorie: %s",
    ["Category sound registered: it plays instead of custom text, without a duplicate announcement."] = "Kategorieton registriert: Er spielt statt eigenem Text, ohne doppelte Ansage.",
    ["Category sound registration pending. It is not ready yet."] = "Registrierung des Kategorietons ausstehend. Er ist noch nicht bereit.",
    ["Category sound registration failed. This effect may remain silent in combat."] = "Registrierung des Kategorietons fehlgeschlagen. Dieser Effekt kann im Kampf stumm bleiben.",
    ["Category sound is not currently registered."] = "Kategorieton ist derzeit nicht registriert.",
    ["No category sound configured. This effect may remain silent in combat."] = "Kein Kategorieton konfiguriert. Dieser Effekt kann im Kampf stumm bleiben.",
    ["Combat: hidden effects may use the configured category instead of your text."] = "Im Kampf können verborgene Effekte den Kategorieton statt deines Textes nutzen.",
    ["Choose a category sound for this effect. It can announce effects hidden in combat, when custom text is unavailable. A registered category sound replaces custom text without a duplicate announcement. Per effect uses each preset effect's own category."] = "Wähle einen Kategorieton für diesen Effekt. Er kann verborgene Effekte im Kampf ansagen, wenn eigener Text nicht verfügbar ist. Ein registrierter Kategorieton ersetzt eigenen Text ohne doppelte Ansage. Pro Effekt nutzt die Kategorie des jeweiligen Presets.",
    ["Choose the category sound for expiration independently of application. Native category sounds require successful registration. Not used by rules that treat their triggers as one effect."] = "Wähle den Kategorieton für den Ablauf unabhängig von der Anwendung. Native Kategorietöne benötigen erfolgreiche Registrierung. Nicht genutzt, wenn Auslöser als ein Effekt behandelt werden.",
    ["Spell lookup"] = "Zaubersuche",
    ["EXPORT GROUP"] = "GRUPPE EXPORTIEREN", ["IMPORT GROUP"] = "GRUPPE IMPORTIEREN",
    ["Copy this text (Ctrl+C) and send it to a friend."] = "Diesen Text kopieren (Strg+C) und an einen Freund schicken.",
    ["Paste a group text here, then click Check. Import always creates a new group."] = "Gruppentext hier einfügen, dann Prüfen klicken. Importieren legt immer eine neue Gruppe an.",
    ["Paste a group text, then click Check."] = "Gruppentext einfügen, dann Prüfen klicken.",
    ["Check"] = "Prüfen", ["Import"] = "Importieren",
    ["Paste a group someone shared with you."] = "Eine Gruppe einfügen, die dir jemand geschickt hat.",
    ["Check passed. Click Import to add the group."] = "Prüfung bestanden. Mit Importieren die Gruppe hinzufügen.",
    ["Text changed. Check it again before importing."] = "Text geändert. Vor dem Importieren erneut prüfen.",
    ["Spell ID %d"] = "Spell-ID %d", ["Unknown spell"] = "Unbekannter Spell",
    ["+ %d more"] = "+ %d weitere",
    ["This group was made for another class."] = "Diese Gruppe stammt von einer anderen Klasse.",
    ["Spoken on application"] = "Gesprochen bei Anwendung", ["Spoken on expiration"] = "Gesprochen bei Ablauf",
    ["Screen text on application"] = "Bildschirmtext bei Anwendung", ["Screen text on expiration"] = "Bildschirmtext bei Ablauf",
    ["On application"] = "Bei Anwendung", ["On expiration"] = "Bei Ablauf",
    ["Plays sound ID %d on %s"] = "Spielt Sound-ID %d auf %s", ["Plays sound %s on %s"] = "Spielt Sound %s auf %s",
    ["Category cue: %s"] = "Kategorie-Hinweis: %s",
    ["Its specializations do not fit your class and are not imported."] = "Ihre Spezialisierungen passen nicht zu deiner Klasse und werden nicht importiert.",
    ["Import window already has text. Clear it first."] = "Das Importfenster enthält schon Text. Zuerst leeren.",
    ["%d spell IDs are unknown to this client."] = "%d Spell-IDs sind diesem Client unbekannt.",
    ["You already track some of these effects in: %s. Both groups would announce them."] = "Du verfolgst einige dieser Effekte bereits in: %s. Beide Gruppen würden sie ansagen.",
    ["Built-in rules cannot be shared."] = "Eingebaute Regeln lassen sich nicht teilen.",
