    ["Only rules with up to 4 items can be shared."] = "Nur Regeln mit bis zu 4 Items lassen sich teilen.",
    ["%s is already tracked in: %s. Both rules would announce it."] = "%s wird bereits verfolgt in: %s. Beide Regeln würden es ansagen.",
    ["Ctrl-click to post in chat."] = "Strg+Klick: im Chat posten.",
