    ["%d s (legacy)"] = "%d s (alt)",
    ["0% warns just before expiry; 100% warns at application. Enable TTS, Sound, or on-screen text below. Percentage warnings need readable duration and expiration."] = "0 % warnt unmittelbar vor Ablauf, 100 % direkt beim Anwenden. Darunter TTS, Sound oder Bildschirmtext aktivieren. Prozentwarnungen benötigen lesbare Laufzeit und Ablaufzeit.",
    ["Choose 1 to 60 seconds. Enable TTS, Sound, or on-screen text below to send warning. Custom warnings need a readable expiration time."] = "1 bis 60 Sekunden wählen. Darunter TTS, Sound oder Bildschirmtext aktivieren. Eigene Vorwarnungen benötigen eine lesbare Ablaufzeit.",
    ["Aura tracker layout and seal-family settings stay local and are not included in shared rules."] = "Aura-Tracker-Layout und Siegel-Familie bleiben lokal und werden nicht in geteilte Regeln übernommen.",
    ["CDM"] = "CDM", ["Aura state is unknown."] = "Aura-Status ist unbekannt.",
    ["Runtime only available in Blizzard CDM."] = "Laufzeit ist nur im Blizzard-CDM verfügbar.",
