    ["Window size"] = "Fenstergröße", ["Drag to resize the window. It stops at a minimum size so everything stays readable."] = "Ziehen ändert die Fenstergröße. Ab einer Mindestgröße ist Schluss, damit alles lesbar bleibt.",
    ["Timeline"] = "Zeitleiste",["Start"] = "Start", ["End"] = "Ende", ["Node"] = "Knoten",
    ["New node"] = "Neuer Knoten", ["Remove node"] = "Knoten entfernen", ["Position"] = "Position",
    ["s after start"] = "s nach Start", ["Duration"] = "Dauer", ["Seconds after start"] = "Sekunden nach Start",
    ["set by you"] = "von dir gesetzt", ["learned: %s s"] = "gelernt: %s s",
    ["unknown until the effect was seen once"] = "unbekannt, bis der Effekt einmal gesehen wurde",
    ["estimated in combat"] = "im Kampf geschätzt",
    ["Adds a notification moment between start and end. Drag it on the line or type its position."] = "Fügt einen Ansagezeitpunkt zwischen Start und Ende hinzu. Auf der Linie ziehen oder Position eintippen.",
    ["Removes the selected node. Start and end stay; switch their outputs off instead."] = "Entfernt den gewählten Knoten. Start und Ende bleiben; schalte stattdessen ihre Ausgaben ab.",
    ["Position of the selected node: 0 % = start, 100 % = end. Decimals allowed."] = "Position des gewählten Knotens: 0 % = Start, 100 % = Ende. Kommazahlen erlaubt.",
    ["Position of the selected node in seconds after the start. Needs a known duration."] = "Position des gewählten Knotens in Sekunden nach dem Start. Braucht eine bekannte Dauer.",
    ["Duration in seconds. Empty uses the last readable duration of this effect. In combat a hidden duration is estimated from it; the end (100 %) always waits for the real end of the effect."] = "Dauer in Sekunden. Leer nutzt die zuletzt lesbare Dauer dieses Effekts. Im Kampf wird eine verborgene Dauer daraus geschätzt; das Ende (100 %) wartet immer auf das echte Ende des Effekts.",
    ["Remove %s?"] = "%s entfernen?",
    ["Click the line to add a node there. Drag a node to move it. Click a selected node again to remove it."] = "Klick auf die Linie fügt dort einen Knoten hinzu. Knoten zum Verschieben ziehen. Ein gewählter Knoten erneut angeklickt wird entfernt (mit Rückfrage).",
    ["s before end"] = "s vor Ende", ["Seconds before end"] = "Sekunden vor Ende",
    ["Position of the selected node in seconds before the end (expiration). Needs a known duration."] = "Position des gewählten Knotens in Sekunden vor dem Ende (Ablauf). Braucht eine bekannte Dauer.",
    ["Timing"] = "Zeitpunkt", ["Percent of the duration"] = "Prozent der Dauer", ["Seconds after start"] = "Sekunden nach Start",
    ["Seconds before end"] = "Sekunden vor Ende", ["s after start"] = "s nach Start",
    ["seconds before the end need a duration"] = "Sekunden vor Ende brauchen eine Dauer",
    ["Percent of the duration, seconds after the start (works without a known duration) or seconds before the end (needs a duration)."] = "Prozent der Dauer, Sekunden nach dem Start (geht ohne bekannte Dauer) oder Sekunden vor dem Ende (braucht eine Dauer).",
    ["Percent or seconds, depending on the timing on the left. Decimals allowed."] = "Prozent oder Sekunden, je nach Zeitpunkt links. Kommazahlen erlaubt.",
    ["Track all ranks"] = "Alle Ränge erfassen",
    ["Every rank of a spell you added counts as that spell (Lay on Hands rank 1, 2 and 3). The ranks are found once in the background and remembered."] = "Jeder Rang eines eingetragenen Zaubers zählt als dieser Zauber (Handauflegung Rang 1, 2 und 3). Die Ränge werden einmal im Hintergrund gesucht und gemerkt.",
    ["Ranks"] = "Ränge", ["All ranks"] = "Alle Ränge", ["All Seals"] = "Alle Siegel",
    ["Every rank of this spell counts (Lay on Hands rank 1, 2 and 3). The ranks are found once in the background and remembered."] = "Jeder Rang dieses Zaubers zählt (Handauflegung Rang 1, 2 und 3). Die Ränge werden einmal im Hintergrund gesucht und gemerkt.",
    ["Paladin: one aura rule with every Seal you know."] = "Paladin: eine Aura-Regel mit allen Siegeln, die du kennst.",
    ["Seals could not be added."] = "Siegel konnten nicht hinzugefügt werden.",
    ["Spells"] = "Zauber", ["Link to group"] = "Mit Gruppe verknüpfen", ["duration unknown"] = "Laufzeit unbekannt",
    ["Shows one track per spell. The group line moves a node for every spell; dragging on a spell's track moves it for that spell only (marked blue). Seconds always belong to that spell's own duration."] = "Zeigt eine Spur pro Zauber. Die Gruppenlinie verschiebt einen Knoten für alle Zauber; Ziehen auf der Spur eines Zaubers verschiebt ihn nur für diesen (blau markiert). Sekunden gehören immer zur eigenen Laufzeit des Zaubers.",
    ["This spell has its own timing for the node. Linking it again makes it follow the group node."] = "Dieser Zauber hat für den Knoten eine eigene Zeit. Verknüpfen lässt ihn dem Gruppen-Knoten wieder folgen.",
    ["Type it with curly braces: {spell}."] = "Mit geschweiften Klammern tippen: {spell}.",
    ["{spell} - name of the spell that triggered the node"] = "{spell} - Name des Zaubers, der den Knoten ausgelöst hat",
    ["{spell} ended  =>  Seal of Wisdom ended"] = "{spell} vorbei  =>  Siegel der Weisheit vorbei",
    ["Without {spell} the text stays as you typed it. In a group, {spell} makes one text fit every spell."] = "Ohne {spell} bleibt der Text, wie du ihn getippt hast. In einer Gruppe passt mit {spell} ein Text für jeden Zauber.",
    ["e.g. {spell} gained"] = "z. B. {spell} erhalten", ["e.g. {spell} ended"] = "z. B. {spell} vorbei",
    ["e.g. {spell} ending soon"] = "z. B. {spell} gleich vorbei", ["e.g. {item} ready"] = "z. B. {item} bereit",
    ["Minimum size"] = "Mindestgröße", ["Maximum size"] = "Maximalgröße",
    ["override"] = "Override", ["overrides"] = "Overrides",
    ["Remove from this spell"] = "Für diesen Zauber entfernen", ["removed for this spell"] = "für diesen Zauber entfernt",
    ["This spell no longer uses the node; the group and the other spells keep it. It stays visible as a faint copy on this track, where you can link it back."] = "Dieser Zauber nutzt den Knoten nicht mehr; Gruppe und andere Zauber behalten ihn. Er bleibt als blasse Kopie auf dieser Spur sichtbar und lässt sich wieder verknüpfen.",
    ["Spell track"] = "Zauber-Spur",
    ["Click the line to add a node for this spell only. Drag a node to move it for this spell."] = "Klick auf die Linie legt einen Knoten nur für diesen Zauber an. Ziehen verschiebt ihn nur für diesen Zauber.",
    ["Window scale"] = "Fenstergröße",
    ["Makes the whole window smaller or larger (70 to 130 %). It never grows beyond what fits on your screen. Applied when you release the slider."] = "Macht das ganze Fenster kleiner oder größer (70 bis 130 %). Es wird nie größer, als auf deinen Bildschirm passt. Gilt, sobald du den Regler loslässt.",
    ["Cooldown"] = "Cooldown",
    ["Start: the spell goes on cooldown. Ready: it comes off cooldown. Nodes in between run on the cooldown's duration; the global cooldown is ignored. WoW may hide cooldown data during combat, so this trigger can miss an event."] = "Start: der Zauber geht auf Cooldown. Bereit: er ist wieder verfügbar. Knoten dazwischen laufen auf der Dauer des Cooldowns; der globale Cooldown zählt nicht. WoW kann Cooldown-Daten im Kampf verbergen, dann kann ein Ereignis fehlen.",
    ["e.g. {item} used"] = "z. B. {item} benutzt",
    ["Press C to open your character window, then click an equipped slot. Press Esc to cancel."] = "Drücke C, um dein Charakterfenster zu öffnen, und klicke dann einen angelegten Platz an. Esc bricht ab.",
    ["Click the line to add a node there. Drag a node to move it. Click a selected node again to remove it. Colours: grey = says nothing, blue = spoken text, green = sound, orange = on-screen text, purple = two of them, gold = all three."] = "Klick auf die Linie legt dort einen Knoten an. Ziehen verschiebt ihn. Ein erneuter Klick auf den gewählten Knoten entfernt ihn. Farben: grau = sagt nichts, blau = gesprochener Text, grün = Sound, orange = Bildschirmtext, lila = zwei davon, gold = alle drei.",
}
